/**
 * Everything the Worker is handed at runtime.
 *
 * Written by hand rather than generated by `wrangler types`, because there are
 * only two bindings and the interesting half of this file is the commentary on
 * which variables are secrets.
 *
 * The Express build read all of this from `process.env`, seeded from a `.env`
 * file it parsed itself. There is no `process` here and no file to read, so
 * every one of them arrives as a binding: `vars` in wrangler.jsonc for the dull
 * ones, `wrangler secret put` for the three that are not.
 */
export interface Env {
  /** Users, projects, interests, sessions. The whole store. */
  DB: D1Database;
  /** The built SPA in dist/, uploaded alongside the Worker. */
  ASSETS: Fetcher;

  /* ── Skill-tag generation (worker/ai.ts) ─────────────────────────────── */

  /** 'deepseek' (default) or 'openai'. Nothing else in the app changes. */
  AI_PROVIDER?: string;
  /** Overrides the provider's default model. */
  AI_MODEL?: string;
  /** Overrides the provider's base URL — a proxy, or an OpenAI-compatible host. */
  AI_BASE_URL?: string;
  /** Secret. `wrangler secret put DEEPSEEK_API_KEY`. */
  DEEPSEEK_API_KEY?: string;
  /** Secret. Only read when AI_PROVIDER=openai. */
  OPENAI_API_KEY?: string;

  /* ── First-run accounts (worker/seed.ts) ─────────────────────────────── */

  /**
   * The Express build seeds these at boot. A Worker has no boot, so seeding is
   * an explicit one-shot call to POST /api/setup, which refuses once any user
   * exists — and refuses outright unless SEED_ADMIN_PASSWORD is set, so a fresh
   * deployment can never be claimed by someone who read the default out of the
   * repository.
   *
   * Both passwords are secrets. Set them with `wrangler secret put`, never in
   * wrangler.jsonc, which is committed.
   */
  SEED_ADMIN_EMAIL?: string;
  SEED_ADMIN_PASSWORD?: string;
  SEED_STAFF_EMAIL?: string;
  SEED_STAFF_PASSWORD?: string;
}
